<?php

namespace App\Models;

use App\Support\LegacyColumns;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;

/**
 * `transfers` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; relationships and PHPRunner
 * event behaviour added below.
 *
 * @property int|null $TransferID
 * @property Carbon|null $ImportDate
 * @property int|null $cID_Customer
 * @property string|null $Pax
 * @property string|null $SupplierCode
 * @property string|null $TransferType
 * @property Carbon|null $TransferDate
 * @property string|null $TransferTime
 * @property string|null $TransferTime_sort
 * @property string|null $From
 * @property string|null $Flight_Ship_Num_From
 * @property int|null $OLP
 * @property string|null $To
 * @property string|null $Assistant
 * @property float|null $Assistant_Price
 * @property int|null $cID_Assistant
 * @property string|null $CoachCompanyID
 * @property string|null $vid
 * @property string|null $CarTypeID
 * @property string|null $PassengerName
 * @property string|null $LeadName
 * @property string|null $LeadPhone
 * @property string|null $LesseeName
 * @property string|null $Notes
 * @property string|null $DriverNotes
 * @property string|null $Status
 * @property string|null $Platform
 * @property Carbon|null $ReferencePeriod
 * @property int|null $ReferenceYear
 * @property float|null $PurchasePrice
 * @property float|null $SalePrice
 * @property float|null $PricePaid
 * @property float|null $PriceRcvd
 * @property float|null $Expense
 * @property string|null $ExpenseRcvd
 * @property string|null $ExpensePaid
 * @property string|null $TobeInvoiced
 * @property string|null $InvoicedIssued
 * @property string|null $InvoicedRcvd
 * @property string|null $SalesInvoiceNum
 * @property string|null $PurchaseInvoiceNum
 * @property float|null $PlatformPrice
 * @property float|null $Assets
 * @property float|null $ExtraIncome
 * @property float|null $Liabilities
 * @property float|null $CashRegister
 * @property float|null $Income
 * @property Carbon|null $CreatedTimestamp
 * @property Carbon|null $ModifiedTimestamp
 * @property string|null $CreatedBy
 * @property string|null $ModifiedBy
 * @property string|null $AssistantStatus
 * @property string|null $VPOS
 * @property string|null $PaymentType
 * @property string|null $PaymentOnHoldFlag
 * @property Carbon|null $Voucher_StartDt
 * @property string|null $Voucher_StartTime
 * @property Carbon|null $Voucher_EndDt
 * @property string|null $Voucher_EndTime
 * @property string|null $order
 * @property int|null $OperationalIssues
 * @property int|null $FinancialIssues
 * @property int|null $OpenCharges
 * @property string|null $TicketsRequested
 * @property string|null $ElorusID
 * @property int|null $order1
 * @property Carbon|null $Voucher_Start_Date_Calc
 * @property string|null $Voucher_Start_StartTime_Calc
 * @property Carbon|null $Voucher_End_Date_Calc
 * @property string|null $Voucher_End_Time_Calc
 * @property string|null $OperationalIssuesFlag
 * @property string|null $FinancialIssuesFlag
 * @property string|null $OpenExpensesFlag
 * @property string|null $OpenChargesFlag
 * @property string|null $AssetsFlag
 * @property string|null $LiabilitiesFlag
 * @property string|null $Files
 * @property string|null $Attachments
 * @property string|null $FLNM
 * @property string|null $DriverReceiptType
 * @property int|null $DriverReceipt
 * @property float|null $TicketsValue
 * @property int|null $SupplierModified
 * @property int|null $TransferLoadID
 * @property string|null $pricecheck
 * @property string|null $TaxiReceipt
 * @property Carbon|null $TaxiReceiptDate
 * @property string|null $TaxiReceipt_Issued
 * @property float|null $TaxiReceiptAmount
 * @property string|null $ElorusTaxiNumber
 * @property int|null $TicketsFlag
 */
class Transfer extends Model
{
    protected $table = 'transfers';

    protected $primaryKey = 'TransferID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'TransferID' => 'integer',
            'ImportDate' => 'date',
            'cID_Customer' => 'integer',
            'TransferDate' => 'date',
            'OLP' => 'integer',
            'Assistant_Price' => 'float',
            'cID_Assistant' => 'integer',
            'ReferencePeriod' => 'date',
            'ReferenceYear' => 'integer',
            'PurchasePrice' => 'float',
            'SalePrice' => 'float',
            'PricePaid' => 'float',
            'PriceRcvd' => 'float',
            'Expense' => 'float',
            'PlatformPrice' => 'float',
            'Assets' => 'float',
            'ExtraIncome' => 'float',
            'Liabilities' => 'float',
            'CashRegister' => 'float',
            'Income' => 'float',
            'CreatedTimestamp' => 'datetime',
            'ModifiedTimestamp' => 'datetime',
            'Voucher_StartDt' => 'date',
            'Voucher_EndDt' => 'date',
            'OperationalIssues' => 'integer',
            'FinancialIssues' => 'integer',
            'OpenCharges' => 'integer',
            'order1' => 'integer',
            'Voucher_Start_Date_Calc' => 'date',
            'Voucher_End_Date_Calc' => 'date',
            'DriverReceipt' => 'integer',
            'TicketsValue' => 'float',
            'SupplierModified' => 'integer',
            'TransferLoadID' => 'integer',
            'TaxiReceiptDate' => 'date',
            'TaxiReceiptAmount' => 'float',
            'TicketsFlag' => 'integer',
        ];
    }

    /** Text fields PHPRunner never takes NULL from a form for; the triggers test `= ''`. */
    public const BLANK_AS_EMPTY_STRING = [
        'Pax', 'SupplierCode', 'TransferType', 'TransferTime', 'From', 'Flight_Ship_Num_From', 'To',
        'Assistant', 'CoachCompanyID', 'CarTypeID', 'PassengerName', 'LeadName', 'LeadPhone',
        'LesseeName', 'Notes', 'DriverNotes', 'Status', 'Platform', 'ExpenseRcvd', 'ExpensePaid',
        'TobeInvoiced', 'InvoicedIssued', 'InvoicedRcvd', 'SalesInvoiceNum', 'PurchaseInvoiceNum',
        'AssistantStatus', 'VPOS', 'PaymentType', 'PaymentOnHoldFlag', 'TicketsRequested', 'ElorusID',
    ];

    /** Columns MariaDB calculates itself (GENERATED ALWAYS); never written from PHP. */
    public const GENERATED = [
        'TransferTime_sort', 'ReferencePeriod', 'ReferenceYear',
        'Assets', 'Liabilities', 'CashRegister', 'Income',
        'Voucher_Start_Date_Calc', 'Voucher_Start_StartTime_Calc', 'Voucher_End_Date_Calc', 'Voucher_End_Time_Calc',
        'OperationalIssuesFlag', 'FinancialIssuesFlag', 'OpenChargesFlag', 'AssetsFlag', 'LiabilitiesFlag',
    ];

    /**
     * PHPRunner's `issues` column (transfers datasource): a non-cancelled transfer with a
     * TBD/TBA placeholder, a missing From/To, or an operational/financial issue flag.
     */
    public function scopeWithOpenIssues(Builder $query): Builder
    {
        return $query->where('Status', '<>', 'Cancelled')->where(fn (Builder $q) => $q
            ->where('Pax', 'like', 'TBD%')
            ->orWhere('Flight_Ship_Num_From', 'like', 'TBD%')
            ->orWhereRaw("ifnull(`From`, '') = ''")->orWhere('From', 'like', 'TBD%')
            ->orWhereRaw("ifnull(`To`, '') = ''")->orWhere('To', 'like', 'TBD%')
            ->orWhere('Notes', 'like', 'TBD%')
            ->orWhere('LeadName', 'like', 'TBD%')
            ->orWhere('LeadPhone', 'like', 'TBD%')
            ->orWhere('LesseeName', 'like', 'TBD%')
            ->orWhere('PassengerName', 'like', 'TBD%')
            ->orWhere('Assistant', 'TBA')
            ->orWhere('TransferTime', 'like', 'TBD%')
            ->orWhere('OperationalIssuesFlag', 'Yes')
            ->orWhere('FinancialIssuesFlag', 'Yes'));
    }

    /** Fields where a value starting with "TBD"/"TBA" is flagged in the list, as in PHPRunner. */
    public const TBD_FIELDS = [
        'Pax' => 'Pax', 'Flight_Ship_Num_From' => 'Flight/ship', 'From' => 'From', 'To' => 'To',
        'TransferTime' => 'Time', 'Notes' => 'Notes', 'DriverNotes' => 'Driver notes',
        'LeadName' => 'Lead name', 'LeadPhone' => 'Lead phone', 'LesseeName' => 'Lessee',
        'PassengerName' => 'Passenger',
    ];

    protected static function booted(): void
    {
        // PHPRunner BeforeAdd / BeforeEdit.
        static::creating(function (Transfer $transfer): void {
            $transfer->CreatedTimestamp = now();
            $transfer->CreatedBy = auth()->user()?->username;
        });

        static::updating(function (Transfer $transfer): void {
            $transfer->ModifiedTimestamp = now();
            $transfer->ModifiedBy = auth()->user()?->username;
        });

        static::saving(function (Transfer $transfer): void {
            foreach (self::GENERATED as $column) {
                $transfer->offsetUnset($column);
            }

            foreach (self::BLANK_AS_EMPTY_STRING as $column) {
                if (array_key_exists($column, $transfer->getAttributes()) && $transfer->getAttribute($column) === null) {
                    $transfer->setAttribute($column, '');
                }
            }
        });

        // PHPRunner AfterAdd / AfterEdit.
        static::saved(function (Transfer $transfer): void {
            DB::statement('CALL `Update_Transfers_Price`(?, ?)', [$transfer->TransferID, (string) auth()->user()?->username]);

            if (! $transfer->wasRecentlyCreated) {
                // Own vehicles: nothing to buy or receive an invoice for.
                DB::update(
                    "UPDATE transfers t INNER JOIN vehicles v ON t.CoachCompanyID = v.VehicleName
                     SET t.PurchasePrice = 0, t.PricePaid = 0, t.InvoicedRcvd = 'Δε θα λάβω'
                     WHERE t.TransferID = ?",
                    [$transfer->TransferID],
                );
            }
        });
    }

    /** Every column except the `Attachments` blob, so lists stay fast. */
    public function scopeWithoutBlobs(Builder $query): Builder
    {
        return $query->select(LegacyColumns::except($this->getTable(), ['Attachments']));
    }

    public function customer(): BelongsTo
    {
        return $this->belongsTo(Counterparty::class, 'cID_Customer', 'CID');
    }

    public function notes(): HasMany
    {
        return $this->hasMany(TransferNote::class, 'TransferID', 'TransferID');
    }

    public function charges(): HasMany
    {
        return $this->hasMany(TransferCharge::class, 'TransferID', 'TransferID');
    }

    public function priceLines(): HasMany
    {
        return $this->hasMany(PriceListTransfer::class, 'TransferID', 'TransferID');
    }

    public function comms(): HasMany
    {
        return $this->hasMany(TransfersComm::class, 'TransferID', 'TransferID');
    }

    public function files(): HasMany
    {
        return $this->hasMany(MyatTransfersFile::class, 'TransferID', 'TransferID');
    }

    /**
     * Labels of the fields still holding a "TBD"/"TBA" placeholder.
     *
     * @return list<string>
     */
    public function placeholderFields(): array
    {
        $fields = [];

        foreach (self::TBD_FIELDS as $column => $label) {
            if (str_starts_with(strtoupper((string) $this->getAttribute($column)), 'TBD')) {
                $fields[] = $label;
            }
        }

        if (str_starts_with(strtoupper((string) $this->Assistant), 'TBA')) {
            $fields[] = 'Assistant';
        }

        if ($this->Platform === 'Ναι' && (float) $this->PlatformPrice === 0.0) {
            $fields[] = 'Platform price';
        }

        if (blank($this->From)) {
            $fields[] = 'From';
        }

        if (blank($this->To)) {
            $fields[] = 'To';
        }

        return array_values(array_unique($fields));
    }

    /**
     * PHPRunner's "sms" field of the transfers list (transfers datasource): the job as a text for the
     * driver, with the driver or partner of the day and their phone. Built by the same SQL.
     *
     * @return array{text: string, phone: string}
     */
    public function smsForDriver(): array
    {
        $driver = "IFNULL(IFNULL((SELECT CONCAT(d.Fullname, '   ', d.MobilePhone) FROM vehicle_assignments va INNER JOIN vehicles v ON va.VehicleID = v.VehicleID INNER JOIN drivers d ON d.DriverID = va.DriverID WHERE va.AssignmentDate = tr.TransferDate AND v.VehicleName = tr.CoachCompanyID LIMIT 1),"
            ." (SELECT CONCAT(c.CounterShortName, '   ', IFNULL(c.Phones, '')) FROM counterparties c WHERE c.CoachName = tr.CoachCompanyID AND IFNULL(c.CoachName, '') <> '' LIMIT 1)), '')";
        $phone = 'IFNULL(IFNULL((SELECT d.MobilePhone FROM vehicle_assignments va INNER JOIN vehicles v ON va.VehicleID = v.VehicleID INNER JOIN drivers d ON d.DriverID = va.DriverID WHERE va.AssignmentDate = tr.TransferDate AND v.VehicleName = tr.CoachCompanyID LIMIT 1),'
            ." (SELECT c.Phones FROM counterparties c WHERE c.CoachName = tr.CoachCompanyID AND IFNULL(c.CoachName, '') <> '' LIMIT 1)), '')";

        $row = DB::selectOne("SELECT CONCAT_WS('\n',
                CONCAT('*Ημερομηνία:* ', IFNULL(DATE_FORMAT(TransferDate, '%d/%m/%Y'), '')),
                CONCAT('*Ωρα Pickup:* ', IFNULL(TransferTime, '')),
                CONCAT('*Άτομα:* ', IFNULL(Pax, '')),
                CONCAT('*Τύπος:* ', IFNULL(TransferType, '')),
                CONCAT('*Σημείο Παραλαβής:* ', IFNULL(`From`, '')),
                CONCAT('*Σημείο Αποβίβασης:* ', IFNULL(`To`, '')),
                CONCAT('*Πληροφορίες:* ', IFNULL(Flight_Ship_Num_From, '')),
                CONCAT('*Όνομα επιβάτη:* ', IFNULL(LeadName, '')),
                CONCAT('*Τηλέφωνο επιβάτη:* ', IFNULL(LeadPhone, '')),
                CONCAT('*Συνοδός - Ξεναγός:* ', IFNULL(Assistant, '')),
                CONCAT('*Οδηγός:* ', {$driver}),
                CONCAT('*Παρατηρήσεις:* ', IF(GetVouchername(tr.CoachCompanyID) = 0, IFNULL(tr.DriverNotes, ''), IF(tr.DriverNotes IS NULL OR tr.DriverNotes = '', IFNULL(tr.Notes, ''), tr.DriverNotes)))
            ) AS sms, {$phone} AS phone FROM transfers tr WHERE tr.TransferID = ?", [$this->getKey()]);

        return ['text' => (string) ($row->sms ?? ''), 'phone' => (string) ($row->phone ?? '')];
    }
}
